/*
 * Synthetic demo population for the feed: about 100 labeled synthetic people.
 * Some post often, some never; comments and like counts come from the same cast
 * (people react mostly to their own Groups and interests). Generated by
 * `python -m server.privacy.demo_population --export-feed web/src/data/population.json`
 * so the feed and the backend seed use the same cast. Not real people.
 */
import type { Author, Post } from "../types/feed";
import population from "./population.json";

/** Initials avatar as an inline SVG (no photos: no real person's likeness). */
export function initialsAvatar(name: string, color: string): string {
  const initials = name
    .replace(/\(synthetic\)/i, "")
    .trim()
    .split(/\s+/)
    .map((w) => w[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><rect width="80" height="80" fill="${color}"/><text x="50%" y="54%" font-family="Arial,sans-serif" font-size="32" font-weight="600" fill="#fff" text-anchor="middle" dominant-baseline="middle">${initials}</text></svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}

const author = (name: string, color: string): Author => ({ name, avatar: initialsAvatar(name, color) });

const ago = (minutes: number) => (minutes < 60 ? `${minutes}m` : minutes < 1440 ? `${Math.floor(minutes / 60)}h` : `${Math.floor(minutes / 1440)}d`);

export const populationPosts: Post[] = population.posts.map((p) => ({
  id: p.id,
  author: { ...author(p.authorName, p.authorColor), community: `${p.groupName} · synthetic` },
  timestamp: ago(p.minutesAgo),
  visibility: "Public",
  text: p.text,
  reactionCount: p.reactionCount,
  commentCount: p.comments.length,
  shareCount: 0,
  comments: p.comments.map((c) => ({ id: c.id, text: c.text, author: author(c.authorName, c.authorColor) })),
}));
